%[text] # refineOCVData sample script
%[text] Run the function without any arguments. It uses default inputs and returns a result.
data = HighVoltageBatteryTool1.refineOCVData;
head(data, 3) %[output:47bbc8bb]
tail(data, 3) %[output:3613b779]
disp(data.Properties.CustomProperties.OCVTemperature) %[output:62cb18dd]
%%
%[text] Assume you have OCV data measured at different temperatures.
Temp = simscape.Value([0, 25, 60], "degC");
SOC_data = [0; 0.1; 0.15; 0.25; 0.75; 0.9; 1];
OCV_data = simscape.Value( ...
  [2.8, 2.9, 3.0; 3.0, 3.1, 3.3; 3.1, 3.2, 3.4; 3.3, 3.4, 3.6; 3.4, 3.5, 3.7; 3.5, 3.6, 3.8; 3.6, 3.9, 4.15], ...
  "V");
%[text] Refine the data.
SOC_refine_interval = 0.01;

data = HighVoltageBatteryTool1.refineOCVData( ...
  Temperature = Temp, ...
  SOC = SOC_data, ...
  SOCInterval = SOC_refine_interval, ...
  OCV = OCV_data );

ocvTemp = data.Properties.CustomProperties.OCVTemperature;

fig = figure; %[output:8befc8ee]
ax = axes(fig); %[output:8befc8ee]
hold(ax, "on") %[output:8befc8ee]
plot(ax, data.SOC, value(data.OCV)); %[output:8befc8ee]
scatter(ax, SOC_data, value(OCV_data)); %[output:8befc8ee]
grid(ax, "on"); %[output:8befc8ee]
xlabel(ax, "State of Charge"); %[output:8befc8ee]
ylabel(ax, "Open Circuit Voltage (" + string(unit(data.OCV)) + ")"); %[output:8befc8ee]
title(ax, "OCV vs SOC at different temperatures"); %[output:8befc8ee]
leg = legend(ax, string(value(ocvTemp)), Direction="reverse", Location="best"); %[output:8befc8ee]
title(leg, "Temperature (" + string(unit(ocvTemp)) + ")") %[output:8befc8ee]
